import { cleanup, render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { Menu, MenuAnchor, MenuPortal, MenuContent, MenuSub, MenuSubTrigger } from './menu';
import { afterEach, describe, it, expect, vi } from 'vitest';

describe('repro: MenuSubTrigger unstable composed ref (React 19)', () => {
  afterEach(cleanup);

  it('does not loop when the parent re-renders', async () => {
    const errorSpy = vi.spyOn(console, 'error').mockImplementation(() => {});
    const renders = { current: 0 };

    function MenuSubSpy() {
      renders.current += 1;
      return (
        <MenuSub>
          <MenuSubTrigger>sub →</MenuSubTrigger>
        </MenuSub>
      );
    }

    function Repro() {
      const [text, setText] = React.useState('');
      return (
        <div>
          <input value={text} onChange={(e) => setText(e.target.value)} />
          <Menu open modal={false} onOpenChange={() => {}}>
            <MenuAnchor />
            <MenuPortal>
              <MenuContent>
                <MenuSubSpy />
              </MenuContent>
            </MenuPortal>
          </Menu>
        </div>
      );
    }

    render(<Repro />);
    const initialRenders = renders.current;
    await userEvent.type(screen.getByRole('textbox'), 'a');

    // If the unstable composed ref caused a detach/attach loop, renders would explode.
    expect(renders.current - initialRenders).toBeLessThan(10);

    expect(console.error).not.toHaveBeenCalledWith(
      expect.stringContaining('Maximum update depth exceeded'),
    );
    errorSpy.mockRestore();
  });
});
